-- =============================================
-- Script SQL: Tabelas e Inserções de Séries e Episódios
-- =============================================

-- Tabela: series
CREATE TABLE IF NOT EXISTS series (
    id INT PRIMARY KEY,
    actors VARCHAR(500),
    genre VARCHAR(100),
    poster VARCHAR(500),
    season INT,
    synopsis TEXT,
    title VARCHAR(255),
    imdb_rating DECIMAL(3, 1)
);

