(84, 'John Hurt, Colin Morgan, Bradley James', 'AVENTURA', 'https://m.media-amazon.com/images/M/MV5BNmI5NDgyZmQtNDc3YS00Mjg0LThmMzEtZjcyNzczOTJlYWY4XkEyXkFqcGc@._V1_SX300.jpg', 5, 'In a medieval kingdom where magic is punishable by death, young sorcerer Merlin, manservant to Prince Arthur and ward of the court physician, meets a dragon and finds he is apart of a great prophecy to bring about the golden age o...', 'Merlin', 7.9),
