(87, 'Jerry Doyle, Mira Furlan, Andreas Katsulas', 'ACAO', 'https://m.media-amazon.com/images/M/MV5BZTRmOWJjMWMtNDljOC00NzNlLWJhODItNjBjOGVkMDYxMzQ0XkEyXkFqcGc@._V1_SX300.jpg', 5, 'In the mid 23rd century, the Earth Alliance space station Babylon 5, located in neutral territory, is a major focal point for political intrigue, racial tensions and various wars over the course of five years.', 'Babylon 5', 8.4),
